 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iLinkJSON { const SOURCE_IDENTIFIER = 'identifier', SOURCE_CODING = 'coding', SOURCE_ORG_REF = 'managingOrganization/reference', SOURCE_VERSION_ID = 'meta/versionId'; public static function deleteNode(\stdClass &$node, string $path): bool; public static function sortJSON(\stdClass $json): \stdClass; } class LinkJSON implements iLinkJSON { private static function &addChildNode(\stdClass &$node, string $name): \stdClass { $node->{$name} = new \stdClass(); return $node->{$name}; } private static function addNodeValue(&$node, string $name, $value): void { if (empty($node->{$name}) || empty((array) $node->{$name})) { $node->{$name} = $value; } else if (is_array($node->{$name})) { $node->{$name}[] = $value; } else { $new = (array) $node->{$name}; $new[] = $value; $node->{$name} = $new; } } public static function &addNode(\stdClass &$node, string $name, $value = ''): \stdClass { if (empty($node->{$name})) { $new = &self::addChildNode($node, $name); } else { $new = is_array($node->{$name}) ? self::addNodeElement($node->{$name}) : $node->{$name}; } if (!empty($value)) { self::addNodeValue($node, $name, $value); return $node; } return $new; } public static function &addNodeEx(\stdClass &$node, string $name, $value): \stdClass { if (empty($value)) { $new = new \stdClass(); return $new; } return self::addNode($node, $name, $value); } public static function addNodeElement(&$node): \stdClass { $el = new \stdClass(); if (is_array($node)) { $node[] = $el; } else { if (empty((array) $node)) { $node = array($el); } else { $node = array($node, $el); } } return $el; } public static function setNodeValue(\stdClass $node, string $name, $value): void { if (empty($node->{$name}) || empty((array) $node->{$name})) { self::addNode($node, $name, $value); } else { $node->{$name} = $value; } } public static function getNodeAttributeValue(\stdClass $node, string $name) { return $